Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
scsi: qla2xxx: Sanitize payload size to prevent member
 overflow

In qla27xx_copy_fpin_pkt() and qla27xx_copy_multiple_pkt(), the frame_size
reported by firmware is used to calculate the copy length into
item->iocb. However, the iocb member is defined as a fixed-size 64-byte
array within struct purex_item.

If the reported frame_size exceeds 64 bytes, subsequent memcpy calls will
overflow the iocb member boundary. While extra memory might be allocated,
this cross-member write is unsafe and triggers warnings under
CONFIG_FORTIFY_SOURCE.

Fix this by capping total_bytes to the size of the iocb member (64 bytes)
before allocation and copying. This ensures all copies remain within the
bounds of the destination structure member.

Fixes: 875386b98857 ("scsi: qla2xxx: Add Unsolicited LS Request and Response Support for NVMe")
Signed-off-by: Jiasheng Jiang <jiashengjiangcool@gmail.com>
Reviewed-by: Himanshu Madhani <hmadhani2024@gmail.com>
Link: https://patch.msgid.link/20260106205344.18031-1-jiashengjiangcool@gmail.com
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
The firmware-provided frame_size can exceed the fixed 64-byte size of the `item->iocb` buffer. Without validation, the calculated total_bytes leads to a buffer overflow during memcpy, potentially causing memory corruption and triggering CONFIG_FORTIFY_SOURCE warnings.

Here is the patch:
  */
 struct purex_item *
 qla27xx_copy_multiple_pkt(struct scsi_qla_host *vha, void **pkt,
 			  struct rsp_que **rsp, bool is_purls,
 			  bool byte_order)
 {
 	struct purex_entry_24xx *purex = NULL;
 	struct pt_ls4_rx_unsol *purls = NULL;
 	struct rsp_que *rsp_q = *rsp;
 	sts_cont_entry_t *new_pkt;
 	uint16_t no_bytes = 0, total_bytes = 0, pending_bytes = 0;
 	uint16_t buffer_copy_offset = 0, payload_size = 0;
 	uint16_t entry_count, entry_count_remaining;
 	struct purex_item *item;
 	void *iocb_pkt = NULL;

 	if (is_purls) {
 		purls = *pkt;
 		total_bytes = (le16_to_cpu(purls->frame_size) & 0x0FFF) -
 			      PURX_ELS_HEADER_SIZE;
 		entry_count = entry_count_remaining = purls->entry_count;
 		payload_size = sizeof(purls->payload);
 	} else {
 		purex = *pkt;
 		total_bytes = (le16_to_cpu(purex->frame_size) & 0x0FFF) -
 			      PURX_ELS_HEADER_SIZE;
 		entry_count = entry_count_remaining = purex->entry_count;
 		payload_size = sizeof(purex->els_frame_payload);
 	}

+	if (total_bytes > sizeof(item->iocb.iocb))
+		total_bytes = sizeof(item->iocb.iocb);
+
 	pending_bytes = total_bytes;
 	no_bytes = (pending_bytes > payload_size) ? payload_size :
 		   pending_bytes;
 	ql_dbg(ql_dbg_async, vha, 0x509a,
 	       "%s LS, frame_size 0x%x, entry count %d\n",
 	       (is_purls ? "PURLS" : "FPIN"), total_bytes, entry_count);

 	item = qla24xx_alloc_purex_item(vha, total_bytes);
 	if (!item)
 		return item;

 	iocb_pkt = &item->iocb;

 	if (is_purls)
 		memcpy(iocb_pkt, &purls->payload[0], no_bytes);
 	else
 		memcpy(iocb_pkt, &purex->els_frame_payload[0], no_bytes);
 	buffer_copy_offset += no_bytes;
 	pending_bytes -= no_bytes;
 	--entry_count_remaining;

 	if (is_purls)
 		((response_t *)purls)->signature = RESPONSE_PROCESSED;
 	else
 		((response_t *)purex)->signature = RESPONSE_PROCESSED;
 	wmb();

 	do {
 		while ((total_bytes > 0) && (entry_count_remaining > 0)) {
 			if (rsp_q->ring_ptr->signature == RESPONSE_PROCESSED) {
 				ql_dbg(ql_dbg_async, vha, 0x5084,
 				       "Ran out of IOCBs, partial data 0x%x\n",
 				       buffer_copy_offset);
 				cpu_relax();
 				continue;
 			}

 			new_pkt = (sts_cont_entry_t *)rsp_q->ring_ptr;
 			*pkt = new_pkt;

 			if (new_pkt->entry_type != STATUS_CONT_TYPE) {
 				ql_log(ql_log_warn, vha, 0x507a,
 				       "Unexpected IOCB type, partial data 0x%x\n",
 				       buffer_copy_offset);
 				break;
 			}

 			rsp_q->ring_index++;
 			if (rsp_q->ring_index == rsp_q->length) {
 				rsp_q->ring_index = 0;
 				rsp_q->ring_ptr = rsp_q->ring;
 			} else {
 				rsp_q->ring_ptr++;
 			}
 			no_bytes = (pending_bytes > sizeof(new_pkt->data)) ?
 				sizeof(new_pkt->data) : pending_bytes;
 			if ((buffer_copy_offset + no_bytes) <= total_bytes) {
 				memcpy(((uint8_t *)iocb_pkt + buffer_copy_offset),
 				       new_pkt->data, no_bytes);
 				buffer_copy_offset += no_bytes;
 				pending_bytes -= no_bytes;
 				--entry_count_remaining;
 			} else {
 				ql_log(ql_log_warn, vha, 0x5044,
 				       "Attempt to copy more that we got, optimizing..%x\n",
 				       buffer_copy_offset);
 				memcpy(((uint8_t *)iocb_pkt + buffer_copy_offset),
 				       new_pkt->data,
 				       total_bytes - buffer_copy_offset);
 			}

 			((response_t *)new_pkt)->signature = RESPONSE_PROCESSED;
 			wmb();
 		}

 		if (pending_bytes != 0 || entry_count_remaining != 0) {
 			ql_log(ql_log_fatal, vha, 0x508b,
 			       "Dropping partial FPIN, underrun bytes = 0x%x, entry cnts 0x%x\n",
 			       total_bytes, entry_count_remaining);
 			qla24xx_free_purex_item(item);
 			return NULL;
 		}
 	} while (entry_count_remaining > 0);

 	if (byte_order)
 		host_to_fcp_swap((uint8_t *)&item->iocb, total_bytes);

 	return item;
 }

  */
 static struct purex_item *
 qla27xx_copy_fpin_pkt(struct scsi_qla_host *vha, void **pkt,
 		      struct rsp_que **rsp)
 {
 	struct purex_entry_24xx *purex = *pkt;
 	struct rsp_que *rsp_q = *rsp;
 	sts_cont_entry_t *new_pkt;
 	uint16_t no_bytes = 0, total_bytes = 0, pending_bytes = 0;
 	uint16_t buffer_copy_offset = 0;
 	uint16_t entry_count, entry_count_remaining;
 	struct purex_item *item;
 	void *fpin_pkt = NULL;

 	total_bytes = (le16_to_cpu(purex->frame_size) & 0x0FFF)
 	    - PURX_ELS_HEADER_SIZE;
+
+	if (total_bytes > sizeof(item->iocb.iocb))
+		total_bytes = sizeof(item->iocb.iocb);
+
 	pending_bytes = total_bytes;
 	entry_count = entry_count_remaining = purex->entry_count;
 	no_bytes = (pending_bytes > sizeof(purex->els_frame_payload))  ?
 		   sizeof(purex->els_frame_payload) : pending_bytes;
 	ql_log(ql_log_info, vha, 0x509a,
 	       "FPIN ELS, frame_size 0x%x, entry count %d\n",
 	       total_bytes, entry_count);

 	item = qla24xx_alloc_purex_item(vha, total_bytes);
 	if (!item)
 		return item;

 	fpin_pkt = &item->iocb;

 	memcpy(fpin_pkt, &purex->els_frame_payload[0], no_bytes);
 	buffer_copy_offset += no_bytes;
 	pending_bytes -= no_bytes;
 	--entry_count_remaining;

 	((response_t *)purex)->signature = RESPONSE_PROCESSED;
 	wmb();

 	do {
 		while ((total_bytes > 0) && (entry_count_remaining > 0)) {
 			if (rsp_q->ring_ptr->signature == RESPONSE_PROCESSED) {
 				ql_dbg(ql_dbg_async, vha, 0x5084,
 				       "Ran out of IOCBs, partial data 0x%x\n",
 				       buffer_copy_offset);
 				cpu_relax();
 				continue;
 			}

 			new_pkt = (sts_cont_entry_t *)rsp_q->ring_ptr;
 			*pkt = new_pkt;

 			if (new_pkt->entry_type != STATUS_CONT_TYPE) {
 				ql_log(ql_log_warn, vha, 0x507a,
 				       "Unexpected IOCB type, partial data 0x%x\n",
 				       buffer_copy_offset);
 				break;
 			}

 			rsp_q->ring_index++;
 			if (rsp_q->ring_index == rsp_q->length) {
 				rsp_q->ring_index = 0;
 				rsp_q->ring_ptr = rsp_q->ring;
 			} else {
 				rsp_q->ring_ptr++;
 			}
 			no_bytes = (pending_bytes > sizeof(new_pkt->data)) ?
 			    sizeof(new_pkt->data) : pending_bytes;
 			if ((buffer_copy_offset + no_bytes) <= total_bytes) {
 				memcpy(((uint8_t *)fpin_pkt +
 				    buffer_copy_offset), new_pkt->data,
 				    no_bytes);
 				buffer_copy_offset += no_bytes;
 				pending_bytes -= no_bytes;
 				--entry_count_remaining;
 			} else {
 				ql_log(ql_log_warn, vha, 0x5044,
 				       "Attempt to copy more that we got, optimizing..%x\n",
 				       buffer_copy_offset);
 				memcpy(((uint8_t *)fpin_pkt +
 				    buffer_copy_offset), new_pkt->data,
 				    total_bytes - buffer_copy_offset);
 			}

 			((response_t *)new_pkt)->signature = RESPONSE_PROCESSED;
 			wmb();
 		}

 		if (pending_bytes != 0 || entry_count_remaining != 0) {
 			ql_log(ql_log_fatal, vha, 0x508b,
 			       "Dropping partial FPIN, underrun bytes = 0x%x, entry cnts 0x%x\n",
 			       total_bytes, entry_count_remaining);
 			qla24xx_free_purex_item(item);
 			return NULL;
 		}
 	} while (entry_count_remaining > 0);
 	host_to_fcp_swap((uint8_t *)&item->iocb, total_bytes);
 	return item;
 }



